import { useId, useRef, useState } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch, JxToast } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLE_OPTIONS = [
  { value: 'owner', label: 'Владелец', meta: 'Полный доступ', group: 'Управление' },
  { value: 'admin', label: 'Администратор', meta: 'Управляет участниками', group: 'Управление' },
  { value: 'member', label: 'Участник', meta: 'Редактирует проекты', group: 'Команда' },
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только просмотр', group: 'Команда' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<{ email: string; role: string } | null>(null);

  const emailRef = useRef<HTMLInputElement>(null);
  const formId = useId();

  const trimmed = email.trim();
  const isValid = EMAIL_PATTERN.test(trimmed);
  const errorText = touched && !isValid
    ? trimmed.length === 0
      ? 'Введите адрес — без него приглашение не отправить'
      : 'Похоже, это не адрес почты. Пример: anna@company.com'
    : undefined;

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) {
      emailRef.current?.focus();
      return;
    }
    setInvited({ email: trimmed, role });
    setEmail('');
    setTouched(false);
    emailRef.current?.focus();
  };

  const invitedRoleLabel = ROLE_OPTIONS.find((option) => option.value === invited?.role)?.label ?? '';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 16px)', maxWidth: '28rem' }}>
      <div aria-live="polite">
        {invited ? (
          <JxToast
            variant="success"
            title="Приглашение отправлено"
            message={`${invited.email} получит роль «${invitedRoleLabel}».`}
            onClose={() => {
              setInvited(null);
              emailRef.current?.focus();
            }}
          />
        ) : null}
      </div>

      <form
        id={formId}
        onSubmit={submit}
        noValidate
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 16px)' }}
      >
        <JxInputField
          ref={emailRef}
          label="Электронная почта"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="anna@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение действует 7 дней. Один адрес за раз."
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        {!notify ? (
          <JxAlert intent="info" title="Уведомление не уйдёт">
            Ссылку-приглашение придётся передать участнику самостоятельно.
          </JxAlert>
        ) : null}

        <div style={{ display: 'flex', gap: 'var(--jx-gap, 8px)' }}>
          <JxButton variant="primary" type="submit" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

